param(
  [string]$Root = (Get-Location).Path,
  [switch]$DryRun
)

$ErrorActionPreference = "Stop"

function Write-Ok([string]$Message) {
  Write-Host "[OK] $Message" -ForegroundColor Green
}

function Write-Info([string]$Message) {
  Write-Host "[..] $Message" -ForegroundColor Cyan
}

function Write-Warn2([string]$Message) {
  Write-Host "[!!] $Message" -ForegroundColor Yellow
}

function Is-IgnoredPath([string]$FullName) {
  return $FullName -match '[\\/](node_modules|\.git|dist|build|coverage)[\\/]'
}

function Find-UniqueFile([string]$Name) {
  $items = @(
    Get-ChildItem -LiteralPath $Root -Recurse -File -Filter $Name -ErrorAction SilentlyContinue |
      Where-Object { -not (Is-IgnoredPath $_.FullName) }
  )

  if ($items.Count -eq 1) {
    return $items[0]
  }

  if ($items.Count -gt 1) {
    Write-Host ""
    Write-Host "Encontrei mais de um '$Name':" -ForegroundColor Yellow
    $items | ForEach-Object { Write-Host "  - $($_.FullName)" }
    throw "Nao consigo escolher com seguranca. Execute com -Root apontando para a pasta apps/web ou remova a ambiguidade."
  }

  return $null
}

function Decode-Utf8([string]$Base64) {
  return [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($Base64))
}

function Write-Utf8NoBom([string]$Path, [string]$Content) {
  $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($Path, $Content, $utf8NoBom)
}

Write-Host ""
Write-Host "Omnimob - Modernizacao dos modais de perfil" -ForegroundColor Magenta
Write-Host "Root: $Root"
Write-Host ""

if (-not (Test-Path -LiteralPath $Root -PathType Container)) {
  throw "A pasta Root nao existe: $Root"
}

$jsxFile = Find-UniqueFile "ModaisDoPerfil.jsx"
if (-not $jsxFile) {
  throw "Nao encontrei ModaisDoPerfil.jsx abaixo de: $Root"
}

$stylesFile = Find-UniqueFile "styles.css"

if (-not $stylesFile) {
  Write-Info "Nao achei um unico styles.css; procurando o CSS pelo marcador dos modais..."

  $cssCandidates = @(
    Get-ChildItem -LiteralPath $Root -Recurse -File -Filter "*.css" -ErrorAction SilentlyContinue |
      Where-Object {
        -not (Is-IgnoredPath $_.FullName) -and
        (Select-String -LiteralPath $_.FullName -Pattern "MODAIS DO PERFIL" -SimpleMatch -Quiet -ErrorAction SilentlyContinue)
      }
  )

  if ($cssCandidates.Count -eq 1) {
    $stylesFile = $cssCandidates[0]
  } elseif ($cssCandidates.Count -gt 1) {
    Write-Host ""
    Write-Host "Encontrei mais de um CSS com o marcador dos modais:" -ForegroundColor Yellow
    $cssCandidates | ForEach-Object { Write-Host "  - $($_.FullName)" }
    throw "Nao consigo escolher com seguranca. Execute com -Root mais especifico."
  } else {
    throw "Nao encontrei styles.css nem um CSS contendo 'MODAIS DO PERFIL'."
  }
}

Write-Info "Componente: $($jsxFile.FullName)"
Write-Info "Estilos:    $($stylesFile.FullName)"

$jsxAtual = [System.IO.File]::ReadAllText($jsxFile.FullName)
$cssAtual = [System.IO.File]::ReadAllText($stylesFile.FullName)

if ($jsxAtual -notmatch 'export function ModalPreferencias' -or
    $jsxAtual -notmatch 'export function ModalMeusDados') {
  throw "O ModaisDoPerfil.jsx encontrado nao parece ser o componente esperado. Nada foi alterado."
}

$novoJsx = Decode-Utf8 ""
$blocoCss = Decode-Utf8 ""

$inicio = "/* === OMNIMOB MODAL PERFIL V2 :: INICIO ==="
$fim = "/* === OMNIMOB MODAL PERFIL V2 :: FIM === */"

if ($cssAtual.Contains($inicio)) {
  $padrao = '(?s)/\* === OMNIMOB MODAL PERFIL V2 :: INICIO ===.*?/\* === OMNIMOB MODAL PERFIL V2 :: FIM === \*/'
  $novoCss = [System.Text.RegularExpressions.Regex]::Replace($cssAtual, $padrao, [System.Text.RegularExpressions.MatchEvaluator]{ param($m) $blocoCss })
  Write-Info "Bloco V2 ja existia no CSS: ele sera atualizado, sem duplicar."
} else {
  $novoCss = $cssAtual.TrimEnd() + [Environment]::NewLine + [Environment]::NewLine + $blocoCss + [Environment]::NewLine
}

if ($DryRun) {
  Write-Host ""
  Write-Warn2 "DRY RUN: nenhum arquivo foi alterado."
  Write-Host "Seriam feitas estas mudancas:"
  Write-Host "  1. Substituir todo o conteudo de ModaisDoPerfil.jsx pela versao moderna."
  Write-Host "  2. Adicionar/atualizar o bloco CSS isolado mpx-* no fim de styles.css."
  Write-Host "  3. Criar backups dos dois arquivos antes da gravacao."
  exit 0
}

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupJsx = "$($jsxFile.FullName).before-modal-v2.$stamp.bak"
$backupCss = "$($stylesFile.FullName).before-modal-v2.$stamp.bak"

Copy-Item -LiteralPath $jsxFile.FullName -Destination $backupJsx
Copy-Item -LiteralPath $stylesFile.FullName -Destination $backupCss

Write-Ok "Backups criados:"
Write-Host "     $backupJsx"
Write-Host "     $backupCss"

try {
  Write-Utf8NoBom $jsxFile.FullName $novoJsx
  Write-Utf8NoBom $stylesFile.FullName $novoCss
} catch {
  Write-Warn2 "Falha durante a gravacao. Restaurando os backups..."
  Copy-Item -LiteralPath $backupJsx -Destination $jsxFile.FullName -Force
  Copy-Item -LiteralPath $backupCss -Destination $stylesFile.FullName -Force
  throw
}

Write-Ok "ModaisDoPerfil.jsx atualizado."
Write-Ok "Bloco visual mpx-* aplicado ao styles.css."

# Checagem simples de integridade do resultado.
$jsxDepois = [System.IO.File]::ReadAllText($jsxFile.FullName)
$cssDepois = [System.IO.File]::ReadAllText($stylesFile.FullName)

if ($jsxDepois -notmatch 'className="mpx-modal' -or
    -not $cssDepois.Contains($inicio) -or
    -not $cssDepois.Contains($fim)) {
  Write-Warn2 "A validacao final falhou. Restaurando os backups..."
  Copy-Item -LiteralPath $backupJsx -Destination $jsxFile.FullName -Force
  Copy-Item -LiteralPath $backupCss -Destination $stylesFile.FullName -Force
  throw "O patch foi revertido automaticamente."
}

Write-Host ""
Write-Ok "Patch concluido."
Write-Host ""
Write-Host "Agora rode o projeto normalmente e abra:" -ForegroundColor Cyan
Write-Host "  - Suas preferencias > Aparencia"
Write-Host "  - Suas preferencias > Atalhos"
Write-Host "  - Meus dados"
Write-Host ""
Write-Host "Se quiser desfazer manualmente, os backups estao ao lado dos arquivos originais." -ForegroundColor DarkGray
